o.del_flag='0'
  and o.activity_id=#{activityId}
  and o.hotel_id=#{hotelId}
  and o.guest_name like concat('%',#{guestName},'%')
  and o.phone like concat('%',#{phone},'%')
  and o.order_status=#{orderStatus}

order by o.order_id desc

mapper.update:
update yc_hotel_order
hotel_id=#{hotelId}, room_id=#{roomId}, guest_name=#{guestName}, phone=#{phone}, check_in_date=#{checkInDate}, check_out_date=#{checkOutDate}, room_count=#{roomCount}, amount=#{amount}, order_status=#{orderStatus}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where order_id=#{orderId}
